#!/usr/bin/env python3
"""Shipment summary builder; rules are in /app/docs/*.md."""
import csv
import gzip
import io
import json
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction
from pathlib import Path

UNIT_KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction("0.45359237"),
    "oz": Fraction("0.028349523125"),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
ID_RE = re.compile(r"^\s*SH\D*?0*(\d+)\s*$", re.I)

# per depot: canonical field -> column name, plus every column name of the depot
COLS = {
    "east": dict(id="id", type="type", shipped="shipped", weight="gross", status="status"),
    "harbor": dict(id="ref", type="rec", shipped="date", weight="weight", status="state"),
    "lakeside": dict(id="id", type="kind", shipped="shipped", weight="gross_kg", status="status"),
    "river": dict(id="ref", type="t", shipped="shipped", weight="weight", status="status"),
    "west": dict(id="id", type="typ", shipped="shipped", weight="weight", status="status"),
}
ALL_COLS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
DELIM = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
BASE_DATE = {"east": "ymd", "lakeside": "iso", "harbor": "iso", "river": "mm/dd/yyyy", "west": "dd.mm.yyyy"}
DECIMAL_COMMA = {"west"}
HARBOR_STATE = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    b = path.read_bytes()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16", "replace")
    head = b[:400]
    if head.count(b"\x00") > 10 and b"\x00" in head[:2]:
        return b.decode("utf-16-be", "replace")
    if head.count(b"\x00") > 10:
        return b.decode("utf-16-le", "replace")
    m = re.search(rb"^#\s*charset\s*:\s*([\w.-]+)", head, re.I | re.M)
    if m:
        try:
            return b.decode(m.group(1).decode("ascii"))
        except (LookupError, UnicodeDecodeError):
            pass
    return b.decode("utf-8", "replace")


# ---------------------------------------------------------------- values
def to_fraction(s, decimal_comma=False):
    s = s.strip().replace(" ", "").replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(s)


def parse_weight(raw, unit, decimal_comma=False):
    """raw may carry its own unit suffix; `unit` is the fallback."""
    if raw is None:
        return None
    raw = str(raw).strip()
    if not raw:
        return None
    m = re.match(r"^([-+0-9.,\s]+?)\s*([A-Za-z]+)?$", raw)
    if not m:
        return None
    u = (m.group(2) or unit or "kg").lower()
    try:
        return to_fraction(m.group(1), decimal_comma) * UNIT_KG[u]
    except (ValueError, KeyError, ZeroDivisionError):
        return None


def norm_status(s):
    return re.sub(r"[\s-]+", "_", (s or "").strip().lower())


def parse_date(s, form):
    """Return (year, month) in UTC for a date/time string, or None."""
    s = (s or "").strip()
    if not s:
        return None
    if re.search(r"\d[T ]\d{2}:\d{2}", s):
        try:
            d = datetime.fromisoformat(s.replace("Z", "+00:00"))
            if d.tzinfo is not None:
                d = d.astimezone(timezone.utc)
            return d.year, d.month
        except ValueError:
            pass
    form = (form or "iso").strip().lower()
    try:
        if form == "serial":
            return ymd(date(1899, 12, 30) + timedelta(days=int(float(s))))
        if form in ("iso", "ymd", "yyyy-mm-dd"):
            return ymd(date.fromisoformat(s[:10]))
        fmts = {"dmy": "%d-%m-%Y", "mm/dd/yyyy": "%m/%d/%Y", "dd/mm/yyyy": "%d/%m/%Y",
                "dd.mm.yyyy": "%d.%m.%Y", "yyyymmdd": "%Y%m%d", "yyyyddd": "%Y%j",
                "d mmm yyyy": "%d %b %Y", "dd mmm yyyy": "%d %b %Y"}
        return ymd(datetime.strptime(s, fmts[form]).date())
    except (ValueError, KeyError):
        return None


def ymd(d):
    return d.year, d.month


def rec_type(t):
    t = (t or "").strip().lower()
    if t in ("c", "cor", "corr", "correction", "amend", "amendment"):
        return "correction"
    if t in ("v", "void"):
        return "void"
    return "new"


def number(raw):
    m = ID_RE.match(raw or "")
    return int(m.group(1)) if m else None


# ---------------------------------------------------------------- parsers
# Each returns (seq, [record]); record = dict(num, type, month, kg, status)

def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    allc = ALL_COLS[depot]
    seq = None
    state = {"unit": None, "date": None}
    header = None
    records = []
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        i += 1
        if line.endswith("\r"):
            line = line[:-1]
        if not line.strip():
            continue
        if line.startswith("#"):
            m = re.search(r"\bseq\s*[=:]\s*(\d+)", line, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            d = re.match(r"^#\s*([A-Za-z][\w ]*?)\s*:\s*(.*?)\s*$", line)
            if d:
                name = re.sub(r"\s+", " ", d.group(1).lower())
                val = d.group(2).strip()
                if name in ("unit", "weight unit"):
                    state["unit"] = val.split()[0].lower() if val else None
                elif name in ("dates", "date format", "date"):
                    state["date"] = val.split()[0] if val else None
            continue
        if delim == ",":  # quoted fields may span lines
            while line.count('"') % 2 == 1 and i < len(lines):
                line += "\n" + lines[i]
                i += 1
            row = next(csv.reader([line], delimiter=",", quotechar='"'))
        else:
            row = line.split(delim)
        low = [f.strip().lower() for f in row]
        if all(f in allc for f in low):
            header = low
            continue
        if header is None:
            continue
        rec = parse_row(depot, cols, header, row, state)
        if rec:
            records.append(rec)
    return seq, records


def parse_row(depot, cols, header, row, state):
    widx = header.index(cols["weight"]) if cols["weight"] in header else None
    row_unit = None
    if len(row) > len(header) and widx is not None:
        j = widx + 1
        if j < len(row) and row[j].strip().lower() in UNIT_KG:
            row_unit = row[j].strip().lower()
            row = row[:j] + row[j + 1:]
        else:
            for j, f in enumerate(row):
                if f.strip().lower() in UNIT_KG:
                    row_unit = f.strip().lower()
                    row = row[:j] + row[j + 1:]
                    break
    row = list(row) + [""] * (len(header) - len(row))
    get = lambda k: row[header.index(cols[k])] if cols[k] in header else ""
    num = number(get("id"))
    if num is None:
        return None
    typ = rec_type(get("type"))
    if typ == "void":
        return dict(num=num, type="void")
    wname = cols["weight"]
    m = re.search(r"_(kg|g|lb|oz)$", wname)
    unit = m.group(1) if m else (row_unit or state["unit"])
    kg = parse_weight(get("weight"), unit, depot in DECIMAL_COMMA)
    status = get("status")
    if depot == "harbor":
        status = HARBOR_STATE.get(status.strip().upper(), status)
    return dict(num=num, type=typ, month=parse_date(get("shipped"), state["date"] or BASE_DATE[depot]),
                kg=kg if kg is not None else Fraction(0), status=norm_status(status))


def parse_north(text):
    seq = None
    records = []
    for line in text.lstrip("﻿").split("\n"):
        if not line.strip():
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "id" not in o:
                meta = o.get("meta")
                if isinstance(meta, dict) and seq is None and "seq" in meta:
                    seq = int(meta["seq"])
                continue
            num = number(str(o["id"]))
            if num is None:
                continue
            typ = rec_type(o.get("kind"))
            if typ == "void":
                records.append(dict(num=num, type="void"))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r"^weight_(kg|g|lb|oz)$", k)
                if m:
                    kg = parse_weight(val, m.group(1))
            if kg is None and "weight" in o:
                kg = parse_weight(o["weight"], o.get("unit"))
            records.append(dict(num=num, type=typ, month=parse_date(o.get("shipped_at"), "iso"),
                                kg=kg if kg is not None else Fraction(0),
                                status=norm_status(o.get("status"))))
    return seq, records


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if root.get("seq") else None
    base = (root.get("weight-unit") or "kg").lower()
    records = []
    for el in root.iter("shipment"):
        num = number(el.get("id"))
        if num is None:
            continue
        typ = rec_type(el.get("type"))
        if typ == "void":
            records.append(dict(num=num, type="void"))
            continue
        w = el.find("weight")
        kg = None
        if w is not None and w.text:
            kg = parse_weight(w.text, (w.get("unit") or base).lower())
        sh = el.find("shipped")
        if sh is not None and sh.text:
            month = parse_date(sh.text, "iso")
        else:
            month = parse_date(el.get("shipped"), "d mmm yyyy")
        st = el.find("status")
        records.append(dict(num=num, type=typ, month=month,
                            kg=kg if kg is not None else Fraction(0),
                            status=norm_status(st.text if st is not None else "")))
    return seq, records


FW = {  # name: (length, id, type, shipped, date form, weight, unit, status)
    "FW1": (42, (0, 9), (9, 10), (10, 17), "yyyyddd", (17, 25), Fraction(1, 1000) , (25, 26)),
    "FW2": (43, (1, 10), (0, 1), (10, 18), "yyyymmdd", (18, 26), Fraction(1, 100), (26, 27)),
    "FW3": (41, (0, 9), (16, 17), (9, 16), "yyyyddd", (17, 24), Fraction("0.45359237") / 10, (24, 25)),
}


def parse_south(text):
    seq = None
    layout = None
    records = []
    by_len = {v[0]: k for k, v in FW.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\x0c" in line or line.startswith("SOUTH DEPOT"):
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\w+)", line)
            if m:
                layout = m.group(1)
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        name = by_len.get(len(line), layout)
        if name not in FW:
            continue
        _, idf, tf, sf, form, wf, factor, stf = FW[name]
        num = number(line[slice(*idf)])
        if num is None:
            continue
        typ = rec_type(line[slice(*tf)])
        if typ == "void":
            records.append(dict(num=num, type="void"))
            continue
        try:
            kg = int(line[slice(*wf)]) * factor
        except ValueError:
            kg = Fraction(0)
        records.append(dict(num=num, type=typ, month=parse_date(line[slice(*sf)], form),
                            kg=kg, status=FW_STATUS.get(line[slice(*stf)].strip().upper(), "")))
    return seq, records


# ---------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_central(b)
    text = decode(b)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    if depot in DELIM:
        return parse_delimited(depot, text)
    raise ValueError("unknown depot " + depot)


def round2(fr):
